def from_roman(s):
    if not isinstance(s, str) or not s:
        raise ValueError('Invalid Roman numeral')
    roman = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        if ch not in roman:
            raise ValueError('Invalid character')
        val = roman[ch]
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    # Validate range and canonical form? We'll just check conversion back?
    # For simplicity we accept any valid roman per algorithm; but spec requires strict form.
    # We'll add validation by converting back using to_roman and compare.
    def to_roman(num):
        vals = [
            (1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),
            (100,'C'),(90,'XC'),(50,'L'),(40,'XL'),
            (10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')
        ]
        res = ''
        for v, sym in vals:
            while num >= v:
                res += sym
                num -= v
        return res
    if not (1 <= total <= 3999):
        raise ValueError('Out of range')
    if to_roman(total) != s:
        raise ValueError('Non-standard form')
    return total

# Test script
tests = [
    ("III", 3),
    ("IV", 4),
    ("IX", 9),
    ("LVIII", 58),
    ("MCMXCIV", 1994),
]
fail = False
for roman, expected in tests:
    try:
        got = from_roman(roman)
        if got != expected:
            print(f'FAIL: {roman} -> {got} expected {expected}')
            fail = True
        else:
            print(f'PASS: {roman} -> {got}')
    except Exception as e:
        print(f'FAIL: {roman} raised {e}')
        fail = True

# Additional invalid cases
invalid = ["IIII", "IC", "", "VX", "DM", "MMMM", "IIV"]
for roman in invalid:
    try:
        got = from_roman(roman)
        print(f'FAIL: {roman} -> {got} (should raise)')
        fail = True
    except ValueError:
        print(f'PASS: {roman} correctly raised')
    except Exception as e:
        print(f'FAIL: {roman} raised unexpected {e}')
        fail = True

if not fail:
    print('ALL TESTS PASSED')
else:
    print('SOME TESTS FAILED')

